{noformat}    public buildBonusPriceLabelForScheduledRides(
        driverConfig: DriverOrderScreenConfig,
        pricingSummary: PricingOrderInternalAsyncApi.PredictionDataResponse | null,
        country: string,
        language: string
    ): UILabel[] {
        const preRideBonus = pricingSummary?.driver.pre_ride_bonus;
        if (!ActiveOrderConfigProvider.activeScheduledOrderShowBonusPrice(driverConfig) || preRideBonus === undefined) {
            return [];
        }

        return [this.priceFormatter.buildBonusPriceLabel(preRideBonus, country, language)];
    }{noformat}

